import{_ as n}from"./chunks/projects-sidebar-manager.1CSA31F-.js";import{_ as a,a as i,b as r,c as s,d as t}from"./chunks/web-panel-016-177.BgfcPA07.js";import{_ as l,o as d,c as o,a3 as h}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"Sidebar Manager","description":"Ordner, Farben, Transparenz und Links in der Home-Assistant-Seitenleiste. Version 0.1.7, DE/EN/FR.","frontmatter":{"title":"Sidebar Manager","description":"Ordner, Farben, Transparenz und Links in der Home-Assistant-Seitenleiste. Version 0.1.7, DE/EN/FR."},"headers":[],"relativePath":"projects/sidebar-manager/index.md","filePath":"projects/sidebar-manager/index.md","lastUpdated":1793634051000}'),u={name:"projects/sidebar-manager/index.md"};function p(g,e,c,b,m,k){return d(),o("div",null,[...e[0]||(e[0]=[h('<h1 id="sidebar-manager" tabindex="-1">Sidebar Manager <a class="header-anchor" href="#sidebar-manager" aria-label="Permalink to &quot;Sidebar Manager&quot;">​</a></h1><img src="'+n+`" width="80" height="80" alt="Sidebar Manager"><p><strong>0.1.7 · Home Assistant ≥ 2026.10.3 · DE / EN / FR · MIT</strong></p><p>Ordner, Farben, Transparenz und eigene Links direkt in „Seitenleiste bearbeiten“. Haupteinträge und Ordner gemeinsam am nativen Ziehgriff sortieren. Keine HA-Systemdateien werden ersetzt.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-manager" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-manager/releases/tag/v0.1.7" target="_blank" rel="noreferrer">Release 0.1.7</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-manager&amp;category=plugin" target="_blank" rel="noreferrer">HACS</a></p><h2 id="hacs-marketplace" tabindex="-1">HACS / Marketplace <a class="header-anchor" href="#hacs-marketplace" aria-label="Permalink to &quot;HACS / Marketplace&quot;">​</a></h2><p>Frontend-Plugin, keine Supervisor-App und keine Dashboard-Karte. <code>https://github.com/rockbaer2007/ha-sidebar-manager</code> als benutzerdefiniertes HACS-Repository in Kategorie <strong>Dashboard</strong> (<code>plugin</code>) hinzufügen und herunterladen. Veröffentlichung bedeutet keine Aufnahme in den Standardkatalog. HACS-kompatible Paketstruktur für Marketplace; noch kein eigener Marketplace-Laufzeittest.</p><p>Vorher HA-Vollbackup erstellen. Im bestehenden <code>frontend:</code>-Abschnitt der <code>configuration.yaml</code> ergänzen; Themes und andere Module erhalten:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Alte Moduleinträge für Sidebar Colors und Sidebar Organizer deaktivieren, nur Sidebar Manager laden. Konfiguration prüfen, HA neu starten und Browser neu laden. Nur eine Dashboard-Ressource genügt für den seitenübergreifenden Einsatz nicht.</p><h2 id="manuelle-installation" tabindex="-1">Manuelle Installation <a class="header-anchor" href="#manuelle-installation" aria-label="Permalink to &quot;Manuelle Installation&quot;">​</a></h2><p><code>ha-sidebar-manager.js</code> aus dem Release nach <code>/config/www/ha-sidebar-manager/ha-sidebar-manager.js</code> kopieren und stattdessen <code>/local/ha-sidebar-manager/ha-sidebar-manager.js</code> als Moduladresse verwenden. HACS- und manuelle Kopie nicht gleichzeitig laden. Das ZIP enthält Bundle, Konfigurationsbeispiele, Lizenz und DE/EN/FR-Anleitungen. Bestehende versionierte lokale Pfade wie <code>/local/ugso-sidebar-manager/0.1.7/ha-sidebar-manager.js</code> dürfen bleiben, wenn die Datei dort liegt. Bei Updates den gewählten Pfad erhalten und Browser neu laden.</p><h2 id="webseiten-rechts-in-ha" tabindex="-1">Webseiten rechts in HA <a class="header-anchor" href="#webseiten-rechts-in-ha" aria-label="Permalink to &quot;Webseiten rechts in HA&quot;">​</a></h2><p>Links in einem neuen Tab benötigen keine weitere Einrichtung. Für <strong>Rechts anzeigen (iframe)</strong> zusätzlich diesen Eintrag in <code>configuration.yaml</code> bzw. die vorhandene <code>panel_custom</code>-Liste übernehmen:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">panel_custom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    embed_iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Bei manueller Installation <code>module_url</code> auf <code>/local/ha-sidebar-manager/ha-sidebar-manager.js</code> ändern. Die Adresse muss mit dem Frontend-Modul übereinstimmen. Prüfen und HA neu starten. Ohne <code>sidebar_title</code> entsteht kein zusätzlicher Menüeintrag. Beispiele: <code>panel-custom.example.yaml</code> und <code>panel-custom.manual.example.yaml</code> im ZIP.</p><p>Die Zielseite muss Einbettung erlauben. CSP/X-Frame-Options, HTTPS-zu-HTTP oder die eigene Anmeldung der Zielseite können die Anzeige verhindern. „In neuem Tab öffnen“ bleibt als Alternative verfügbar. Keine HA-Tokens werden an Webseiten übergeben; HA-Zugriffsrechte bleiben wirksam.</p><h2 id="bedienung" tabindex="-1">Bedienung <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Bedienung&quot;">​</a></h2><p>Den Seitenleistenkopf länger gedrückt halten. Farbfelder, Augen und Ziehgriffe bleiben im HA-Dialog; „Gruppen und Links verwalten“ öffnet den Manager. DE/EN/FR folgen der HA-Sprache, Englisch dient als Rückfall.</p><ul><li>Farben und Deckkraft je Eintrag; „Theme-Farbe“ entfernt die eigene Farbe. Das Schachbrett kennzeichnet Transparenz.</li><li>Ordner mit Namen, MDI-Icon, Farbe und anfänglichem Ein-/Ausklappen. Bestehende Menüeinträge und eigene Links zuordnen; „Hauptmenü“ verschiebt sie zurück.</li><li>Ordner zwischen Haupteinträge ziehen. Ordner und Inhalt wandern als Block; Alt+Auf/Ab unterstützt die Tastaturbedienung.</li><li>Unten angeheftete Ordner stehen auch im Editor unten. Verschieben vor einen normalen Menüblock hebt die untere Anheftung auf. Abbrechen erhält Position und Anheftung.</li><li>Trennlinie <strong>0–4 px</strong>, 0 = Aus. Nur ausgeklappt sichtbar, am Ende des Untermenüs, in Icon-Farbe/Transparenz, mit jeweils 1 px Abstand oben und unten.</li><li>Logs, Automationen und Zustände mit auswählbarem Ordner hinzufügen. Vorhandene passende Links werden wiederverwendet; Namen und Icons bleiben änderbar.</li><li>Eigene interne Links sind in den Einstellungen hellgelb, externe HTTP(S)-Links hellblau. Extern: neuer Tab oder iframe. Alte Links behalten ihre bisherige Öffnungsart bis zur Änderung. Eigene Seitenleistenfarben bleiben erhalten.</li><li>Speichern im Manager übernimmt dessen Organisation. Farben/native Reihenfolge im darunterliegenden HA-Dialog dort separat speichern. Abbrechen verwirft den jeweiligen Entwurf.</li></ul><p>Einstellungen, Profil und Benachrichtigungen bleiben nativ. Ausblenden und Gruppieren ändern keine Zugriffsrechte.</p><h2 id="bilder-und-prufstand" tabindex="-1">Bilder und Prüfstand <a class="header-anchor" href="#bilder-und-prufstand" aria-label="Permalink to &quot;Bilder und Prüfstand&quot;">​</a></h2><p><img src="`+a+'" alt="Farbwähler"></p><p><img src="'+i+'" alt="Linkoptionen"></p><p><img src="'+r+'" alt="Ordnerposition in 0.1.7"></p><p><img src="'+s+'" alt="Eingeklappter Ordner ohne Trennlinie"></p><p><img src="'+t+'" alt="Webseite rechts innerhalb von HA"></p><p>0.1.7 auf HA <strong>2026.10.4</strong>, Port 80 geprüft: Speichern/Abbrechen, angehefteten Testordner verschieben, Neuladen, Gruppenzuordnung und Trennlinien nur bei ausgeklapptem Menü. Frühere Prüfungen decken Farben, Transparenz, Links, iframe/neuen Tab und Export/Import ab. Daten und Testdashboard erhalten, eigene Testobjekte entfernt. <strong>60 automatische Tests erfolgreich.</strong> Bilder der Farb-/Linkfunktionen aus 0.1.6 zeigen weiter gültige Funktionen. <a href="https://github.com/rockbaer2007/ha-sidebar-manager/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Prüfbericht</a>.</p><p>2026.10.3 ist die vorgesehene Mindestversion, keine separat live geprüfte Installation. Keine pauschale Kompatibilitätszusage für alle Webseiten oder Marketplace-Versionen.</p><h2 id="einstellungen-erhalten-und-umsteigen" tabindex="-1">Einstellungen erhalten und umsteigen <a class="header-anchor" href="#einstellungen-erhalten-und-umsteigen" aria-label="Permalink to &quot;Einstellungen erhalten und umsteigen&quot;">​</a></h2><ol><li>Vollbackup erstellen und vorhandene Organizer-Einstellungen sowie Manager-/Farbsicherungen exportieren.</li><li>Alte Sidebar-Module deaktivieren; Dateien und Benutzereinstellungen erhalten. Nur eine Manager-Kopie installieren.</li><li>Sidebar-Colors-Farben bleiben unter <code>ugso_sidebar_colors_v1</code>, Manager-Organisation unter <code>ugso_sidebar_manager_v1</code>, pro HA-Benutzer auf dem Server synchronisiert.</li><li><strong>Kein automatischer Organizer-YAML-/Layoutimport.</strong> Export aufbewahren und gewünschte Gruppen/Links manuell anlegen.</li></ol><p>Fehlende Panels bleiben gespeichert. Ladefehler/unbekannte Formate überschreiben keine Einstellungen. Vor Änderungen wird der vorherige Organisationsstand im Browser gesichert; gesperrte Ablage verhindert das Speichern. Konflikte werden vorab geprüft, unklare Bestätigungen nachgelesen. Ein enges gleichzeitiges Schreibfenster bleibt ohne atomaren Serververgleich möglich.</p><p>JSON-Export/Import betrifft Gruppen, Links, Namen, Icons, Sichtbarkeit, Anheftung, Reihenfolge und Trennlinien; keine Zugangsdaten oder nativen HA-Einstellungen. Eintragsfarben haben eine getrennte Sicherung. Zurücksetzen wirkt zunächst nur auf den Entwurf. Für Rückkehr alten Moduleintrag wiederherstellen, HA neu starten und Browser neu laden; Benutzerdaten behalten.</p><h2 id="entwicklung-und-grenzen" tabindex="-1">Entwicklung und Grenzen <a class="header-anchor" href="#entwicklung-und-grenzen" aria-label="Permalink to &quot;Entwicklung und Grenzen&quot;">​</a></h2><p>Node ≥22: <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. Tags bauen JS und ZIP automatisch. Interne HA-Dialoge können sich mit Frontend-Updates ändern. Keine gerätespezifischen Layouts, freien CSS-/Template-Aktionen, automatische Organizer-Migration oder Kopf-/Breiteneinstellungen.</p><p>Eigene UGSo-Implementierung auf Basis von Sidebar Colors. <a href="https://github.com/ngocjohn/sidebar-organizer" target="_blank" rel="noreferrer">Sidebar Organizer von Viet Ngoc</a> dient als Funktionsreferenz; kein Organizer-Quellcode eingebettet. MIT-Lizenz im Repository.</p>',36)])])}const z=l(u,[["render",p]]);export{_ as __pageData,z as default};
